class Solution {
    public int minMoves(int target, int maxDoubles) {
        int l = Math.min(maxDoubles, 31 - Integer.numberOfLeadingZeros(target));
        int high = target >> l;
        int low = target & ((1 << l) - 1);
        return high - 1 + l + Integer.bitCount(low);
    }
}

